    "hero.badge": "ஆப்பிரிக்கர்களால், உலகத்திற்காக கட்டப்பட்டது",
    "hero.title1": "எதிர்காலத்தைக் கட்டியெழுப்புதல்",
    "hero.title2": "நாம் விரும்புகிறோம்",
    "hero.subtitle": "சில நிமிடங்களில் வலைத்தளங்கள், மொபைல் பயன்பாடுகள் மற்றும் டிஜிட்டல் தயாரிப்புகளை உருவாக்கவும். நீங்கள் விரும்புவதை விவரிக்கவும். குறியீடு தேவையில்லை, வடிவமைப்பாளர்கள் தேவையில்லை, தொழில்நுட்ப திறன்கள் தேவையில்லை. ஆப்பிரிக்காவில் உருவாக்கப்பட்டது, அனைவருக்கும்.",
