    "features.badge": "அம்சங்கள்",
    "features.title1": "உங்களுக்குத் தேவையான அனைத்தும்",
    "features.title2": "உருவாக்கி வெளியிடுங்கள்",
    "features.subtitle": "யோசனையிலிருந்து App Store வரை. AI இன் சக்தியுடன் தொழில்முறை வலைத்தளங்கள் மற்றும் மொபைல் பயன்பாடுகளை வடிவமைக்கவும், உருவாக்கவும், வரிசைப்படுத்தவும்.",
    "features.website.title": "வலைத்தள உருவாக்கி",
    "features.website.desc": "எங்கள் இழுத்து விடும் உருவாக்கியுடன் அழகான, பதிலளிக்கக்கூடிய வலைத்தளங்களை உருவாக்கவும். குறியீட்டு அனுபவம் தேவையில்லை.",
    "features.app.title": "ஆப் வடிவமைப்பாளர்",
    "features.app.desc": "iOS மற்றும் Android க்கான மொபைல் பயன்பாடுகளை வடிவமைக்கவும். நிகழ்நேரத்தில் முன்னோட்டம் பார்த்து நேரடியாக ஆப் ஸ்டோர்களில் வெளியிடவும்.",
    "features.ai.title": "AI அரட்டை உதவியாளர்",
    "features.ai.desc": "எங்கள் AI உதவியாளரிடமிருந்து உடனடி உதவி பெறவும். கேள்விகள் கேளுங்கள், குறியீட்டு பரிந்துரைகளைப் பெறவும், நிகழ்நேரத்தில் சிக்கல்களைத் தீர்க்கவும்.",
    "features.store.title": "App Store வெளியீடு",
    "features.store.desc": "ஒரே கிளிக்கில் Apple App Store மற்றும் Google Play Store இல் வெளியிடவும். நாங்கள் அனைத்து சிக்கல்களையும் கையாளுகிறோம்.",
    "features.code.title": "குறியீடு உருவாக்கம்",
    "features.code.desc": "AI தூய்மையான, உற்பத்திக்கு தயாராக உள்ள குறியீட்டை உருவாக்குகிறது. உங்கள் திட்டத்தை ஏற்றுமதி செய்யுங்கள் அல்லது நாங்கள் ஹோஸ்ட் செய்ய அனுமதிக்கவும்.",
    "features.security.title": "பாதுகாப்பானது மற்றும் நம்பகமானது",
    "features.security.desc": "நிறுவன-தர பாதுகாப்பு மற்றும் 99.9% செயல்பாட்டு நேரம். உங்கள் பயன்பாடுகள் பாதுகாப்பானவை, விரைவானவை மற்றும் எப்போதும் கிடைக்கின்றன.",
    "africa.title1": "ஆப்பிரிக்கா எழுகிறது.",
    "africa.title2": "வரம்புகள் இல்லாத புதுமை.",
    "africa.desc": "ஆப்பிரிக்கா உலகின் மிக இளம் மற்றும் வேகமாக வளரும் மக்கள்தொகையின் தாயகமாகும். Afro AI உடன், ஒவ்வொரு கனவு காண்பவரும், தொழில்முனைவோரும், படைப்பாளியும் தங்கள் பார்வையை யதார்த்தமாக மாற்ற முடியும். சமூகங்களை மாற்றும், வாய்ப்புகளை உருவாக்கும், கண்டத்தின் டிஜிட்டல் எதிர்காலத்தை வடிவமைக்கும் பயன்பாடுகளை உருவாக்குங்கள்.",
    "africa.item1": "Ubuntu-உத்வேகம் பெற்ற ஒத்துழைப்பு கருவிகள்",
    "africa.item2": "ஆப்பிரிக்க நெட்வொர்க்குகளுக்கான மொபைல்-முதல் வடிவமைப்பு",
    "africa.item3": "Pesapal உடன் உள்ளூர் கட்டண ஒருங்கிணைப்பு",
    "africa.item4": "ஆப்பிரிக்க மொழிகளுக்கான பன்மொழி ஆதரவு",
    "pricing.badge": "விலை",
    "pricing.title1": "நியாயமான விலை",
    "pricing.title2": "ஒவ்வொரு படைப்பாளிக்கும்",
    "pricing.subtitle": "ஆப்பிரிக்க புதுமையாளர்களுக்காக வடிவமைக்கப்பட்ட மலிவான திட்டங்கள். இலவசமாகத் தொடங்குங்கள், வளர்ந்தபடி அளவிடுங்கள்.",
