    "quote.desc": "நாங்கள் கட்டியெழுப்பும் அனைத்தையும் வழிநடத்தும் ஒரு ஆப்பிரிக்க பழமொழி. Afro AI என்பது ஒரு கருவிக்கு மேற்பட்டது — இது ஒவ்வொரு ஆப்பிரிக்க படைப்பாளியையும் நமது கண்டத்தின் எதிர்காலத்தை வடிவமைக்கும் தொழில்நுட்பத்தை உருவாக்க அதிகாரம் அளிக்கும் ஒரு இயக்கம்.",
